import random
from fractions import Fraction

def bubble_pass(sequence):
    n = len(sequence)
    for i in range(n):
        for j in range(0, n-i-1):
            if sequence[j] > sequence[j+1]:
                sequence[j], sequence[j+1] = sequence[j+1], sequence[j]
    return sequence

def is_visited_in_sequence(sequence):
    return sequence[29] == 39  # 30th position is index 29 in zero-based indexing

def simulate_bubble_pass(num_trials=100000):
    count_success = 0
    for _ in range(num_trials):
        sequence = random.sample(range(40), 40)
        sequence = list(sequence)
        sequence = bubble_pass(sequence)
        if is_visited_in_sequence(sequence):
            count_success += 1
    return Fraction(count_success, num_trials)

# Simulate the process
probability = simulate_bubble_pass()
print(probability)
